export function ImageGrid({ images, onTap }) {
  const { width } = useWindowDimensions();
  const columns = width < 600 ? 2 : 3;
  // simple cache placeholder
  const cache = useRef(new Map()).current;

  const renderItem = ({ item, index }) => (
    <TouchableOpacity onPress={() => onTap(index)}>
      <Image source={{ uri: item }} style={{ width: width / columns, height: width / columns }} resizeMode="cover"/>
